<script setup>
import { ref } from 'vue';import ConfirmDialog from './ConfirmDialog.vue'
defineProps({records:{type:Array,default:()=>[]}});const emit=defineEmits(['delete']);const expanded=ref('');const pendingDelete=ref('')
const moodEmoji={很好:'😄',不错:'🙂',一般:'😐',低落:'😔',很难受:'😣'}
function parts(value){const d=new Date(value);return {date:new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric'}).format(d),time:new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}).format(d)}}
function confirmDelete(){emit('delete',pendingDelete.value);if(expanded.value===pendingDelete.value)expanded.value='';pendingDelete.value=''}
</script>
<template><section class="history-section"><div class="section-heading"><div><p class="eyebrow">最近记录</p><h2>回看最近的心情</h2></div><p v-if="records.length">共 {{ records.length }} 条</p></div><div v-if="records.length" class="history-list"><article v-for="record in records" :key="record.id" :class="['history-item',{expanded:expanded===record.id}]"><button class="history-summary" type="button" :aria-expanded="expanded===record.id" @click="expanded=expanded===record.id?'':record.id"><div class="history-date"><strong>{{ parts(record.createdAt).date }}</strong><span>{{ parts(record.createdAt).time }}</span></div><div class="history-main"><h3>{{ moodEmoji[record.mood] }} {{ record.mood }} <span>· {{ record.intensity }}/10</span></h3><div class="mini-tags"><span v-for="tag in record.emotionTags.slice(0,2)" :key="tag">{{ tag }}</span></div><p class="history-context">{{ record.triggerTags.slice(0,2).join(' / ') || '未选择触发因素' }}</p><p class="history-note">{{ record.note || '这次没有留下文字。' }}</p></div><span class="expand-mark">{{ expanded===record.id?'−':'+' }}</span></button><Transition name="fade"><div v-if="expanded===record.id" class="history-detail"><div><span>当时写下</span><p>{{ record.note || '这次没有留下文字。' }}</p></div><div class="detail-grid"><div><span>情绪感受</span><p>{{ record.emotionTags.join('、') || '未选择' }}</p></div><div><span>触发因素</span><p>{{ record.triggerTags.join('、') || '未选择' }}</p></div><div><span>当时需要</span><p>{{ record.need || '未选择' }}</p></div><div><span>推荐行动</span><p>{{ record.primaryAction || '未保存' }}</p></div></div><div class="saved-insight"><span>当时的洞察</span><p>{{ record.insightSummary || '这条旧记录没有保存洞察摘要。' }}</p></div><button class="delete-link" type="button" @click="pendingDelete=record.id">删除这条记录</button></div></Transition></article></div><div v-else class="empty-state compact"><span>◌</span><h3>第一条记录会出现在这里</h3><p>保存一次心情后，就可以随时回来看看。</p></div><ConfirmDialog :open="!!pendingDelete" @cancel="pendingDelete=''" @confirm="confirmDelete"/></section></template>
